using System.Collections.Concurrent;

var hits = new ConcurrentDictionary<string, int>();
Parallel.For(0, 10_000, _ =>
{
    hits.TryGetValue("home", out int count); // step 1: read
    hits["home"] = count + 1;                 // step 2: write, maybe stale
});
Console.WriteLine(hits["home"]); // often far below 10000, varies per run

using System.Collections.Concurrent;

var hits = new ConcurrentDictionary<string, int>();
Parallel.For(0, 10_000, _ =>
{
    // one call: the update is applied to the latest value, retried if needed
    hits.AddOrUpdate("home", 1, (_, count) => count + 1);
});
Console.WriteLine(hits["home"]); // 10000

