using System.Collections.Concurrent;

public sealed class RateCache(IRateApi api)
{
    private readonly ConcurrentDictionary<string, Lazy<Task<decimal>>> _rates = new();

    public Task<decimal> GetAsync(string currency) =>
        _rates.GetOrAdd(currency, c => new(() => api.GetRateAsync(c))).Value;
}
